package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_equals_TriageGen0Test {

    @Test
    public void testEquals_SameInstance() {
        Element element = Parser.parseBodyFragment("<div></div>").selectFirst("div");
        // Test: if (this == o) return true;
        Assert.assertTrue(element.equals(element));
    }

    @Test
    public void testEquals_Null() {
        Element element = Parser.parseBodyFragment("<div></div>").selectFirst("div");
        // Test: if (o == null || getClass() != o.getClass()) return false;
        Assert.assertFalse(element.equals(null));
    }

    @Test
    public void testEquals_DifferentClass() {
        Element element = Parser.parseBodyFragment("<div></div>").selectFirst("div");
        TextNode textNode = Parser.parseBodyFragment("text").textNodes().get(0);
        // Test: if (o == null || getClass() != o.getClass()) return false;
        Assert.assertFalse(element.equals(textNode));
    }

    @Test
    public void testEquals_DifferentSuperEquals() {
        // The implementation calls super.equals(o). 
        // In Jsoup, Node.equals compares the identity/structure depending on the version, 
        // but the provided code snippet has a logical quirk: 
        // it returns 'this == o' at the end, which is redundant if it passed the first check.
        // However, to trigger the 'if (!super.equals(o)) return false;' branch, 
        // we need two different Element objects that are not considered equal by the superclass (Node).

        Element element1 = Parser.parseBodyFragment("<div></div>").selectFirst("div");
        Element element2 = Parser.parseBodyFragment("<span></span>").selectFirst("span");

        // Since they are different nodes in different trees, super.equals(o) will be false.
        Assert.assertFalse(element1.equals(element2));
    }

    @Test
    public void testEquals_SameContentButDifferentInstance() {
        // This tests the specific logic provided:
        // "return this == o;" at the end of the method.
        // Even if the content is the same, if they are different instances, 
        // and if super.equals(o) were to pass (which it won't for different node instances),
        // the method would return false because this != o.

        Element element1 = Parser.parseBodyFragment("<div></div>").selectFirst("div");
        Element element2 = Parser.parseBodyFragment("<div></div>").selectFirst("div");

        // In Jsoup, Node.equals usually checks if it's the same instance or specific properties.
        // If element1 and element2 are different instances, super.equals(element2) is false.
        Assert.assertFalse(element1.equals(element2));
    }
}
